   for(let i=0;i<=16;i++)I.at(9.5+i*.06,()=>{m.rise=.82+.18*i/16;const f=X.fl();m.hl.y=lerp(fy+T*14,f-T*3.4,i/16);m.hr.y=m.hl.y});I.at(9.6,()=>{DG.music.sfx('eye',1);DG.music.sfx('glow',.8)});
